// Generated by tools/track-builder/src/build-outlines.ts. Do not edit.
export interface Outline {
  /** track width in drawing units (the box is 1000×1000) */
  width: number;
  /** coarse centreline, for thumbnails */
  outline: string;
  /** start line: x, y, heading in degrees */
  start: [number, number, number];
  lapMs: number;
  lengthM: number;
  cornerCount: number;
  /** lap times (ms) for each medal; Pole is every corner purple */
  medals: { bronze: number; silver: number; gold: number };
  /** the circuit's real 2025 pole lap (ms), a time only, or null for invented circuits */
  realPoleMs: number | null;
}

/** The hero map's paths, in outline-detail/<id>.json (see loadOutlineDetail). */
export interface OutlineDetail {
  /** fine centreline, for the hero ribbon */
  ribbon: string;
  /** the optimal racing line */
  line: string;
  /** one open path per corner group (controls.complexes order), along the optimal line */
  groups: string[];
  /** animateMotion timing so a car laps at the optimal lap's speeds */
  keyTimes: string;
  keyPoints: string;
}

